HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>茆书 · 考点导航</title>
<link rel="stylesheet" href="/assets/katex/katex.min.css"><link rel="stylesheet" href="/math-render.css"><script src="/assets/katex/katex.min.js"></script><script src="/math-render.js"></script>
<style>
:root{--ink:#172c41;--muted:#687b8c;--line:#dce5e8;--green:#17675d;--bg:#f4f7f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.75 "Segoe UI","Microsoft YaHei",sans-serif}main{max-width:1320px;margin:auto;padding:28px 30px 70px}nav{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}a{color:var(--green);text-decoration:none}h1{font-size:36px;line-height:1.3;margin:25px 0 12px;letter-spacing:-1px}h2{font-size:21px;margin:0 0 16px}h3{font-size:16px;margin:0 0 8px}.intro{color:var(--muted);max-width:800px}.label{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--green)}.card{padding:24px;background:white;border:1px solid var(--line);border-radius:16px;margin:20px 0;box-shadow:0 3px 13px #142a3810}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.badge,.chip{display:inline-block;border-radius:18px;background:#eaf3f0;color:var(--green);padding:4px 12px;font-size:12px;margin:3px}textarea{display:block;width:100%;min-height:125px;resize:vertical;font:inherit;border:1px solid #ccd9dc;border-radius:10px;padding:16px;margin:12px 0;background:#fcfdfd}button,select{font:inherit;border:1px solid #cad8db;border-radius:8px;background:white;padding:9px 14px;color:var(--ink);cursor:pointer}button:hover{border-color:var(--green)}button.primary{background:var(--green);border-color:var(--green);color:white;padding:11px 23px}button:disabled{opacity:.5;cursor:wait}.preset{padding:6px 11px;color:#4d6575;font-size:13px}.grid{display:grid;grid-template-columns:1.15fr 1fr;gap:22px;align-items:start}.grid .card{margin:0 0 20px}.muted{color:var(--muted);font-size:13px}.notice{background:#fff8e8;border-left:3px solid #d7ab53;padding:12px 15px;border-radius:5px;color:#7b622e}.prose{white-space:pre-wrap;line-height:1.95}.question{padding:15px 0;border-bottom:1px solid #e5ecee}.question:last-child{border:0}.question p{margin:7px 0 12px}.source{border:0;background:#f0f5f6;font-size:12px;padding:5px 9px;margin:3px}.answer{background:#f5f8f6;padding:12px;border-radius:6px;margin-top:10px}details{margin-top:16px}summary{cursor:pointer;color:var(--muted);font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#f5f7f8;padding:15px;border-radius:7px}#graph{width:100%;max-height:650px}#graph rect{cursor:pointer}#error{color:#a53535}dialog{border:1px solid #d0dcdf;border-radius:14px;max-width:1000px;width:90vw;max-height:93vh;padding:22px}dialog::backdrop{background:#102d43a0}dialog img{display:block;width:100%;height:auto}footer{margin-top:35px;color:var(--muted);font-size:12px}.pillrow{margin:8px 0}.proof{padding:14px;background:#f1f7f5;border-radius:10px;margin:12px 0}.graphhelp{background:#f4f7f6;padding:12px;border-radius:8px}label{font-size:13px}#output{scroll-margin-top:15px}@media(max-width:900px){main{padding:20px 16px}.grid{grid-template-columns:1fr}h1{font-size:28px}.card{padding:18px}}
</style><main><nav><strong>茆书 / 考点导航</strong><div class="row"><span class="badge">第一章预览</span><a href="/problems">全书课后题与例题</a><a href="/pilot">教材核对</a><a href="/legacy">早期样板</a></div></nav>
<div class="label" style="margin-top:30px">Probability · Study with evidence</div><h1>从一道题，找到一条学习路径。</h1><p class="intro">定位考点，补齐先修知识，再找一道值得练的相关题。每条依据都可以回到教材原页；提示、思路和计算示例逐层展开。 <a href="/library">打开全书资料库 →</a></p>
<section class="card"><label for="question">输入题目或学习问题</label><textarea id="question" placeholder="例如：掷三颗骰子，最大点数恰好等于4的概率是多少？">掷三颗骰子，最大点数恰好等于4的概率是多少？</textarea><div class="row"><button class="preset" data-question="掷三颗骰子，最大点数恰好等于4的概率是多少？">改编骰子题</button><button class="preset" data-question="看到检测阳性后，为什么不能直接把准确率当成患病概率？">贝叶斯与先验</button><button class="preset" data-question="袋中原有一颗球，不知道黑白，放入白球后抽到白球，原球为白色的概率？">条件不足的题</button><button class="preset" data-question="如何证明最大似然估计的一致性？">检查覆盖范围</button></div><div class="row between" style="margin-top:18px"><div class="row"><label for="mode">检索</label><select id="mode"><option value="adaptive">自适应 + 图谱</option><option value="hybrid">混合检索</option><option value="bm25">BM25 对照</option></select><label for="stage">辅导层级</label><select id="stage"><option value="hint">给我提示</option><option value="steps">展开思路</option><option value="solution">推导 / 计算示例</option></select></div><button class="primary" id="run">开始定位</button></div><div class="row muted" style="margin-top:12px"><label><input type="checkbox" id="llm" disabled> 使用已配置的模型服务</label><span id="runtime">正在读取本地资料状态…</span></div><div id="error" role="alert"></div></section>
<p class="muted" id="catalog"></p><div id="output"></div><footer>私人学习预览 · 题目与考点由助手对照原页整理，教师复核待完成。相似题不等于同题，检索得分不代表正确概率。原始教材和课程资料保留在本机。</footer></main>
<dialog id="viewer"><div class="row between"><strong id="viewer-title">教材原页</strong><button id="close-viewer">关闭原页</button></div><img id="viewer-image" alt="教材原始页面"></dialog>
<script>
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current;const routeLabels={hybrid_graph:'检索与图谱关联',bounded_multi_retrieval:'补检先修知识',single_retrieval:'单次检索',clarify_with_evidence:'需要确认条件',outside_first_chapter:'当前章节未覆盖',clarify_conditions:'请补充题干',clarify_or_add_material:'依据不足'};
const sources=cs=>(cs||[]).map(c=>'<button class="source" data-page="'+c.pdf_page+'">'+esc(c.id)+' · 印刷第'+esc(c.printed_page)+'页</button>').join('');
const qcard=q=>'<article class="question"><span class="label">习题 '+esc(q.section)+' · 第'+q.number+'题</span><h3>'+esc(q.title)+'</h3><p>'+MathView.prose(q.text)+'</p><p class="muted">'+esc(q.relation_reason||'候选相关题，请核对条件')+'</p>'+sources(q.citations)+'<div class="row"><button class="preset" data-fill="'+esc(q.id)+'">以此题继续学习</button><button class="preset" data-answer="'+esc(q.id)+'">查看教材答案参考</button></div><div id="answer-'+esc(q.id)+'"></div></article>';
function prose(text){return MathView.prose(text).replace(/\[(P\d+)\]/g,(m,id)=>{const c=current?.citations?.find(c=>c.id===id);return c?'<button class="source" data-page="'+c.pdf_page+'">'+id+'</button>':m;});}
function drawGraph(g){const cs=g.nodes.filter(n=>n.kind==='concept').slice(0,7),qs=g.nodes.filter(n=>n.kind==='exercise').slice(0,5);const positions={};cs.forEach((n,i)=>positions[n.id]=[130,40+i*68]);qs.forEach((n,i)=>positions[n.id]=[520,55+i*85]);let h=520,svg='<svg id="graph" viewBox="0 0 680 '+h+'" role="img" aria-label="当前题目的考点与相关练习图谱"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#96b4ad"/></marker></defs>';
for(const e of g.edges){const a=positions[e.from],b=positions[e.to];if(!a||!b)continue;svg+='<path d="M'+a[0]+','+a[1]+' Q'+((a[0]+b[0])/2-20)+','+((a[1]+b[1])/2)+' '+b[0]+','+b[1]+'" fill="none" stroke="'+(e.kind==='requires'?'#c4b47f':'#b5ccc6')+'" stroke-width="1.4" marker-end="url(#arrow)"/>';}
for(const n of [...cs,...qs]){const p=positions[n.id];svg+='<g data-node="'+esc(n.id)+'" tabindex="0" role="button" aria-label="'+esc(n.label)+'"><rect x="'+(p[0]-108)+'" y="'+(p[1]-18)+'" width="216" height="36" rx="10" fill="'+(n.kind==='concept'?'#e9f4ef':'#f2f5f9')+'" stroke="#cadcd7"/><text x="'+p[0]+'" y="'+(p[1]+5)+'" text-anchor="middle" font-size="13" fill="#214c44">'+esc(n.label.slice(0,17))+'</text><title>'+esc(n.label)+'</title></g>';}
return svg+'</svg><p class="muted">绿色节点：考点；右侧：练习。连线表示考查或先修关系，教学关系仍待教师复核。点击节点查看说明。</p><div id="graph-detail" class="graphhelp">选择一个节点查看依据。</div>';}
async function go(){const button=$('run');button.disabled=true;$('error').textContent='';try{const r=await fetch('/api/learn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('question').value,mode:$('mode').value,stage:$('stage').value,use_llm:$('llm').checked})});const d=MathView.register(await r.json());if(!r.ok)throw Error(d.error||'查询失败');current=d;let html='<div class="row between"><h2>你的学习路径</h2><span class="badge">'+esc(routeLabels[d.route]||d.route)+' · '+d.total_seconds+' 秒</span></div>';
if(d.status!=='evidence_found'){html+='<section class="card"><p>'+esc(d.teaching.text)+'</p></section>';$('output').innerHTML=html;return;}
html+='<div class="grid"><div><section class="card"><span class="label">'+(d.teaching.llm_used?'模型依据资料生成':'离线教材指引')+'</span><h2 style="margin-top:8px">'+($('stage').value==='hint'?'先从这里想起':'思路与依据')+'</h2><div class="prose">'+prose(d.teaching.text)+'</div>';
if(d.teaching.calculation)html+='<div class="notice">计算示例的前提：'+esc(d.teaching.calculation.assumptions.join('；'))+'。参数按你的输入重算。</div>';
if(d.provider.status!=='not_requested'&&!d.provider.used)html+='<p class="notice">模型调用未完成：'+esc(d.provider.status)+'。当前展示离线指引。</p>';
html+='</section><section class="card"><h2>对应考点</h2>'+d.concepts.map(c=>'<div class="proof"><h3>'+esc(c.label)+'</h3><p>'+MathView.prose(c.text)+'</p>'+sources(c.citations)+'</div>').join('')+'</section><section class="card"><h2>题目知识图谱</h2>'+drawGraph(d.graph)+'</section></div><aside><section class="card"><h2>先核对这几道题</h2>'+d.matches.map(qcard).join('')+'</section><section class="card"><h2>继续练什么</h2>'+((d.related||[]).map(qcard).join('')||'<p class="muted">当前模式不扩展图谱相关练习。</p>')+'</section></aside></div><details class="card"><summary>查看检索路径与运行记录</summary><pre>'+esc(JSON.stringify({semantic:d.semantic,trace:d.trace,request_id:d.request_id,collection:d.collection},null,2))+'</pre></details>';html+='<details class="card"><summary>反馈这次关联的问题</summary><p class="muted">仅保存到本地待处理清单，供教师复核。</p><div class="row"><label for="feedback-record">相关题目</label><select id="feedback-record">'+d.matches.map(q=>'<option value="'+esc(q.id)+'">习题'+esc(q.section)+' 第'+q.number+'题</option>').join('')+'</select><select id="feedback-category" aria-label="问题类型"><option value="wrong_concept">考点关联不合适</option><option value="wrong_formula">公式或条件有误</option><option value="wrong_source">来源页或题号有误</option><option value="other">其他问题</option></select></div><textarea id="feedback-message" aria-label="问题说明" placeholder="请说明发现的问题及依据"></textarea><button id="feedback-save">保存本地反馈</button><span id="feedback-status" class="muted"></span></details>';$('output').innerHTML=html;
}catch(e){$('error').textContent=e.message;}finally{button.disabled=false;}}
document.addEventListener('click',async e=>{if(e.target.id==='feedback-save'){e.target.disabled=true;try{const r=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({record_id:$('feedback-record').value,category:$('feedback-category').value,message:$('feedback-message').value})});const d=MathView.register(await r.json());$('feedback-status').textContent=d.message||d.error;}catch(err){$('feedback-status').textContent=err.message;}finally{e.target.disabled=false;}return;}const p=e.target.closest('[data-page]');if(p){$('viewer-title').textContent='教材印刷第'+(Number(p.dataset.page)-22)+'页 / PDF第'+p.dataset.page+'页';$('viewer-image').src='/book-page/'+p.dataset.page+'.png';$('viewer').showModal();return;}const a=e.target.closest('[data-answer]');if(a){a.disabled=true;try{const r=await fetch('/api/exercise?id='+encodeURIComponent(a.dataset.answer));const d=MathView.register(await r.json());if(!r.ok)throw Error(d.error);$('answer-'+a.dataset.answer).innerHTML='<div class="answer"><strong>教材答案参考 · 待教师复核</strong><p>'+MathView.prose(d.answer?.text||'本题答案尚未整理，请回看教材或由教师核对。')+'</p>'+sources(d.answer?.citations||[])+'</div>';}catch(err){$('error').textContent=err.message;}finally{a.disabled=false;}return;}const f=e.target.closest('[data-fill]');if(f){const q=[...(current?.matches||[]),...(current?.related||[])].find(q=>q.id===f.dataset.fill);if(q){$('question').value=q.text;$('question').focus();window.scrollTo({top:0,behavior:'smooth'});}return;}const n=e.target.closest('[data-node]');if(n){const id=n.dataset.node;const c=[...(current?.concepts||[]),...(current?.prerequisites||[])].find(c=>'concept:'+c.id===id);const q=[...(current?.matches||[]),...(current?.related||[])].find(q=>'exercise:'+q.id===id);$('graph-detail').innerHTML=c?'<strong>'+esc(c.label)+'</strong><p>'+MathView.prose(c.text)+'</p>'+sources(c.citations):q?'<strong>'+esc(q.title)+'</strong><p>'+MathView.prose(q.text)+'</p>':'';}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-node]'))e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));});$('close-viewer').onclick=()=>$('viewer').close();$('run').onclick=go;document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{$('question').value=b.dataset.question;go();});
fetch('/api/course').then(r=>r.json()).then(d=>{$('catalog').textContent=d.exercise_count+'道原页整理题 · '+d.concept_count+'张考点卡 · 全章OCR '+d.raw_candidate_count+'道候选题仍待审';$('runtime').textContent=d.semantic.ready?'本地中文向量已就绪；无需云GPU':'当前使用词法检索；向量索引未就绪';$('llm').disabled=!(d.provider.enabled&&d.provider.configured);if(!$('llm').disabled)$('runtime').textContent+=' · 可选模型服务已配置';}).catch(e=>$('runtime').textContent='资料状态读取失败：'+e.message);
</script></html>'''
